import{_ as e,o as n,c as i,a2 as s}from"./chunks/framework.BW2T23B9.js";const u=JSON.parse('{"title":"架构总览","description":"","frontmatter":{},"headers":[],"relativePath":"developer/architecture.md","filePath":"developer/architecture.md","lastUpdated":1787830168000}'),t={name:"developer/architecture.md"};function l(o,a,p,r,c,d){return n(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h1><p>Turna 客户端采用 Clean Architecture 风格分层，并使用 Provider、ChangeNotifier、GetIt / Injectable 和 Auto Route。分层目标是限制数据所有权和依赖方向，不是增加形式目录。</p><h2 id="目录职责" tabindex="-1">目录职责 <a class="header-anchor" href="#目录职责" aria-label="Permalink to &quot;目录职责&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lib/</span></span>
<span class="line"><span>  application/   状态容器、应用服务、工作流编排</span></span>
<span class="line"><span>  core/          FSRS、语言检测、纯函数与基础策略</span></span>
<span class="line"><span>  courses/       课程 loader 与 validator</span></span>
<span class="line"><span>  data/          drift 数据库、DAO、Repository 实现</span></span>
<span class="line"><span>  di/            GetIt / Injectable 注册</span></span>
<span class="line"><span>  domain/        不可变领域模型与 Repository 接口</span></span>
<span class="line"><span>  routing/       Auto Route 与启动守卫</span></span>
<span class="line"><span>  service/       偏好、TTS、本地服务</span></span>
<span class="line"><span>  views/         页面与组件</span></span></code></pre></div><h2 id="依赖方向" tabindex="-1">依赖方向 <a class="header-anchor" href="#依赖方向" aria-label="Permalink to &quot;依赖方向&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>views</span></span>
<span class="line"><span>  -&gt; application</span></span>
<span class="line"><span>  -&gt; domain &lt;- data</span></span>
<span class="line"><span>  -&gt; core</span></span>
<span class="line"><span></span></span>
<span class="line"><span>application -&gt; domain / core</span></span>
<span class="line"><span>data -&gt; domain</span></span>
<span class="line"><span>domain -&gt; no UI dependency</span></span></code></pre></div><p>界面不直接执行数据库迁移或课程文件写入。领域模型不依赖 Flutter Widget。</p><h2 id="状态管理" tabindex="-1">状态管理 <a class="header-anchor" href="#状态管理" aria-label="Permalink to &quot;状态管理&quot;">​</a></h2><p>Provider + ChangeNotifier 同时承担状态广播和应用服务注入。复杂功能拆分为专用 provider，<code>GameProvider</code> 等 facade 只负责聚合和转发，不复制状态。</p><p>并发状态必须显式表示。例如复习评分使用 in-flight 集合阻止评分与撤销竞态，AI 使用取消令牌和幂等键控制在途请求。</p><h2 id="依赖注入" tabindex="-1">依赖注入 <a class="header-anchor" href="#依赖注入" aria-label="Permalink to &quot;依赖注入&quot;">​</a></h2><p>GetIt 与 Injectable 注册 renderer、service 和 repository。生成文件由 <code>build_runner</code> 产生并提交。新增注解后需要重新生成；普通业务代码修改不需要。</p><h2 id="路由" tabindex="-1">路由 <a class="header-anchor" href="#路由" aria-label="Permalink to &quot;路由&quot;">​</a></h2><p>全屏页面使用 Auto Route。<code>CourseReadyGuard</code> 在课程数据库未准备完成时重定向到启动页。底部主 Tab 使用 IndexedStack，不伪装为 push/pop 路由。</p><p>平台默认：</p><ul><li>Android：Material 路由和预测返回。</li><li>iOS / macOS：Cupertino 路由和边缘返回。</li><li>Web：无页面转场。</li></ul><p>调用点不直接构造任意 <code>MaterialPageRoute</code>、<code>CupertinoPageRoute</code> 或自定义 PageRouteBuilder。</p><h2 id="渲染插件" tabindex="-1">渲染插件 <a class="header-anchor" href="#渲染插件" aria-label="Permalink to &quot;渲染插件&quot;">​</a></h2><p>13 种 Interaction renderer 通过 Injectable 注册并按 <code>runtimeType</code> 查找。新增题型需要同时修改：</p><ol><li>领域 union / 序列化。</li><li>renderer。</li><li>DI 生成。</li><li>Python 与 Dart validator。</li><li>JSON 示例和测试。</li><li>文档。</li></ol><h2 id="ai-边界" tabindex="-1">AI 边界 <a class="header-anchor" href="#ai-边界" aria-label="Permalink to &quot;AI 边界&quot;">​</a></h2><p><code>application/ai/engine/</code> 是唯一 LLM 流量出口。引擎只暴露 chat 与结构化请求；课程、提示、SRS 和教材导入分别持有领域 Prompt 和解析规则。</p><h2 id="anki-边界" tabindex="-1">Anki 边界 <a class="header-anchor" href="#anki-边界" aria-label="Permalink to &quot;Anki 边界&quot;">​</a></h2><p>Android 生产 Official-first 路径位于 <code>application/anki_official/</code>。Collection 与 scheduler 拥有正式卡片状态。Legacy 路径只承担受控迁移与测试，不是生产自动降级。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/developer/local-data">本地数据模型</a></li><li><a href="/docs/developer/testing">测试与质量门禁</a></li><li><a href="/docs/guide/features">核心能力一览</a></li></ul>`,26)])])}const b=e(t,[["render",l]]);export{u as __pageData,b as default};
